/* Deadlock ShipForge Phase 2 world/economy layer.
 * Persistent owned/NPC ships, component condition, dealers, salvage, repair and traffic identity.
 * Engine-neutral state: all durable records are plain JSON and can migrate to Godot resources later.
 */
(function(root){
'use strict';
const F=root.ShipForge;
if(!F)throw new Error('ShipForge must load before ShipForgeWorld');
const SCHEMA='deadlock.shipforge.world.v1';
const VERSION='1.0.0';
const slots=['core','cockpit','wing','engine','weapon','cargo','utility'];
const clone=v=>JSON.parse(JSON.stringify(v));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=n=>new Intl.NumberFormat('en-US').format(Math.round(Number(n)||0))+' cr';
function hash(v){return F.hashSeed(v)}
function rng(seed){let s=hash(seed);return()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return(s>>>0)/4294967296;}}
function pick(a,r){return a[Math.min(a.length-1,Math.floor(r()*a.length))]}
function now(){try{return new Date().toISOString()}catch{return ''}}
function state(data){return ensure(data)}
function nextId(st,prefix='sf'){st.sequence=Number(st.sequence||0)+1;return `${prefix}-${st.sequence.toString(36)}-${hash(`${prefix}|${st.sequence}`).toString(16).slice(0,6)}`}
function currentLocationId(data){return data?.galaxyState?.currentLocationId||'blackglass_station'}
function classLabel(id){return F.catalog.classes[id]?.label||id}
function part(id){return F.part(id)}
function conditionLabel(n){n=Number(n||0);return n>=90?'PRISTINE':n>=70?'GOOD':n>=45?'WORN':n>0?'DAMAGED':'DESTROYED'}
function rarityRank(r){return({common:1,uncommon:2,rare:3,prototype:4})[r]||1}
function conditionClass(n){return n>=75?'good':n>=40?'warn':'danger'}

const RAVEN_PARTS={
 core:'core_twinboom_09',cockpit:'cockpit_armored_05',wing:'wing_outrigger_09',engine:'engine_military_06',weapon:'weapon_rotary_09',cargo:'cargo_modular_08',utility:'utility_smuggler_06'
};
const RAVEN_CONDITION={core:96,cockpit:94,wing:91,engine:93,weapon:90,cargo:98,utility:95};

function newWorld(){return{schema:SCHEMA,version:VERSION,sequence:0,marketCycle:0,encounterSerial:0,activeShipId:'raven',managedShipId:'raven',ships:{},components:{},dealers:{},npcShips:{},traffic:{},salvage:[],salvagedEncounters:{},logs:[]}}
function createInstance(st,partId,opts={}){
 const p=part(partId);if(!p)throw new Error('Unknown ShipForge part '+partId);
 const id=opts.id||nextId(st,'cmp');
 const rec={id,partId,slot:p.slot,condition:clamp(opts.condition??100,0,100),ownerId:opts.ownerId||'rovan',installedOn:opts.installedOn||null,source:opts.source||'inventory',acquiredAt:opts.acquiredAt||now(),paid:Number(opts.paid??0),notes:opts.notes||'',damage:[]};
 st.components[id]=rec;return rec;
}
function shipFromBlueprint(st,blueprint,opts={}){
 const id=opts.id||blueprint.id||nextId(st,'ship');
 const ship={schema:'deadlock.shipforge.persistent-ship.v1',id,name:opts.name||classLabel(blueprint.classId),classId:blueprint.classId,seed:blueprint.seed,palette:blueprint.palette,markings:blueprint.markings||0,wear:blueprint.wear||0,registry:opts.registry||blueprint.registry||null,owner:{id:opts.ownerId||'rovan',name:opts.ownerName||'Rovan Kes',kind:opts.ownerKind||'player'},installations:{},status:opts.status||'operational',hull:Number(opts.hull??100),shields:Number(opts.shields??100),fuel:Number(opts.fuel??100),damageLog:[],createdAt:opts.createdAt||now(),lastSeenAt:opts.lastSeenAt||now(),persistentKey:opts.persistentKey||null};
 for(const slot of slots){const pid=blueprint.parts?.[slot];if(!pid)continue;const cond=opts.conditions?.[slot]??100;const inst=createInstance(st,pid,{condition:cond,ownerId:ship.owner.id,installedOn:id,source:opts.source||'factory'});ship.installations[slot]=inst.id;}
 st.ships[id]=ship;return ship;
}
function initRaven(data,st){
 if(st.ships.raven)return st.ships.raven;
 const bp=F.generate('deadlock-raven-phase2','light_freighter',{id:'raven',palette:'black_copper',parts:RAVEN_PARTS,markings:3,wear:2,registry:'RVN-DL-01'});
 const legacy=data.ship||{};
 return shipFromBlueprint(st,bp,{id:'raven',name:'The Raven',registry:'RVN-DL-01',ownerId:'rovan',ownerName:data.character?.name||'Rovan Kes',ownerKind:'player',conditions:RAVEN_CONDITION,source:'legacy-raven',hull:legacy.hull??100,shields:legacy.shields??100,fuel:legacy.fuel??100});
}
function ensure(data){
 if(!data||typeof data!=='object')throw new Error('Campaign data required');
 let st=data.shipForge;
 if(!st||st.schema!==SCHEMA){const old=st;st=newWorld();data.shipForge=st;if(old&&typeof old==='object')st.legacy=old;}
 st.version=VERSION;st.ships=st.ships||{};st.components=st.components||{};st.dealers=st.dealers||{};st.npcShips=st.npcShips||{};st.traffic=st.traffic||{};st.salvage=st.salvage||[];st.salvagedEncounters=st.salvagedEncounters||{};st.logs=st.logs||[];st.sequence=Number(st.sequence||0);st.marketCycle=Number(st.marketCycle||0);st.encounterSerial=Number(st.encounterSerial||0);st.activeShipId=st.activeShipId||'raven';st.managedShipId=st.managedShipId||st.activeShipId||'raven';
 initRaven(data,st);if(!st.ships[st.activeShipId])st.activeShipId='raven';if(!st.ships[st.managedShipId]||st.ships[st.managedShipId]?.owner?.kind!=='player')st.managedShipId=st.activeShipId;
 recalcAll(data);ensureDealers(data,currentLocationId(data));return st;
}
function shipRecord(data,id){const st=ensure(data);return st.ships[id||st.activeShipId]||null}
function installedInstances(data,shipOrId){const st=data.shipForge?.schema===SCHEMA?data.shipForge:ensure(data),ship=typeof shipOrId==='string'?st.ships[shipOrId]:shipOrId;if(!ship)return[];return slots.map(slot=>{const id=ship.installations?.[slot],inst=id&&st.components[id];return inst?{slot,inst,part:part(inst.partId)}:null}).filter(Boolean)}
function blueprint(data,shipOrId){const ship=typeof shipOrId==='string'?shipRecord(data,shipOrId):shipOrId||shipRecord(data);if(!ship)return null;const parts={};for(const x of installedInstances(data,ship))parts[x.slot]=x.inst.partId;return F.generate(ship.seed||hash(ship.id),ship.classId,{id:ship.id,palette:ship.palette,parts,markings:ship.markings,wear:ship.wear,registry:ship.registry})}
function effectiveStats(data,shipOrId){
 const ship=typeof shipOrId==='string'?shipRecord(data,shipOrId):shipOrId||shipRecord(data);if(!ship)return null;
 const raw={mass:0,armor:0,speed:0,power:0,damage:0,capacity:0,sensors:0,utility:0,value:0};const eff={...raw};let condSum=0,n=0;
 for(const {inst,part:p} of installedInstances(data,ship)){const c=clamp(inst.condition,0,100),f=c<=0?0:.32+.68*c/100;condSum+=c;n++;for(const k of ['mass','armor','speed','power','damage','capacity','sensors','utility']){const v=Number(p?.[k]||0);raw[k]+=v;eff[k]+=k==='mass'?v:v*f;}raw.value+=Number(p?.credits||0);eff.value+=Number(p?.credits||0)*(.25+.75*c/100);}
 const hullMax=Math.max(30,Math.round(72+eff.armor*2.7+eff.mass*.55));
 const shieldsMax=Math.max(20,Math.round(74+eff.power*2.35+eff.utility*.25));
 const fuelMax=Math.max(30,Math.round(78+eff.capacity*.55+eff.power*.85));
 const attackMod=clamp(Math.round((eff.damage+eff.power*.22)/4)-1,-2,8);
 const evasionBonus=clamp(Math.round(eff.speed-eff.mass*.34),-3,8);
 const dice=eff.damage>=17?3:eff.damage>=8?2:1,die=eff.damage>=9?8:6,bonus=Math.max(0,Math.round(eff.power/4));
 return{raw,effective:eff,condition:n?Math.round(condSum/n):100,hullMax,shieldsMax,fuelMax,attackMod,evasionBonus,damageFormula:`${dice}d${die}+${bonus}`,value:Math.round(eff.value)};
}
function recalcShip(data,shipOrId){const ship=typeof shipOrId==='string'?shipRecord(data,shipOrId):shipOrId||shipRecord(data);if(!ship)return null;ship.stats=effectiveStats(data,ship);ship.signature=F.signature(blueprint(data,ship));return ship.stats}
function recalcAll(data){const st=data.shipForge||newWorld();for(const s of Object.values(st.ships||{}))recalcShip(data,s)}
function syncLegacyShip(data){
 const st=ensure(data),ship=st.ships[st.activeShipId]||st.ships.raven;if(!ship||!data.ship)return null;const d=recalcShip(data,ship),legacy=data.ship;
 const ratios={h:clamp(Number(legacy.hull??ship.hull)/Math.max(1,Number(legacy.hullMax||d.hullMax)),0,1),s:clamp(Number(legacy.shields??ship.shields)/Math.max(1,Number(legacy.shieldsMax||d.shieldsMax)),0,1),f:clamp(Number(legacy.fuel??ship.fuel)/Math.max(1,Number(legacy.fuelMax||d.fuelMax)),0,1)};
 legacy.hullMax=d.hullMax;legacy.shieldsMax=d.shieldsMax;legacy.fuelMax=d.fuelMax;legacy.hull=Math.round(d.hullMax*ratios.h);legacy.shields=Math.round(d.shieldsMax*ratios.s);legacy.fuel=Math.round(d.fuelMax*ratios.f);legacy.shipForgeStats=clone(d);legacy.dogfight=legacy.dogfight||{};legacy.dogfight.attackMod=d.attackMod;legacy.dogfight.evasionBonus=d.evasionBonus;legacy.dogfight.damage=d.damageFormula;
 ship.hull=legacy.hull;ship.shields=legacy.shields;ship.fuel=legacy.fuel;ship.stats=clone(d);return d;
}
function log(st,text,type='info'){st.logs.unshift({ts:now(),type,text});st.logs=st.logs.slice(0,60)}
function inventory(data,ownerId='rovan'){const st=ensure(data);return Object.values(st.components).filter(x=>x.ownerId===ownerId&&!x.installedOn)}
function playerShips(data){const st=ensure(data);return Object.values(st.ships).filter(s=>s.owner?.kind==='player')}
function canInstall(data,ship,inst){const p=part(inst?.partId);return !!ship&&!!p&&F.compatible(p,ship.classId)&&F.catalog.classes[ship.classId]?.slots?.includes(p.slot)}
function install(data,shipId,instanceId){
 const st=ensure(data),ship=st.ships[shipId],inst=st.components[instanceId];if(!ship||!inst)return{ok:false,message:'Ship or component unavailable.'};if(inst.installedOn&&inst.installedOn!==shipId)return{ok:false,message:'Component is installed on another ship.'};if(!canInstall(data,ship,inst))return{ok:false,message:`${part(inst.partId)?.name||inst.partId} does not fit ${classLabel(ship.classId)} mounts.`};
 const slot=inst.slot,oldId=ship.installations[slot];if(oldId&&oldId!==instanceId){const old=st.components[oldId];if(old)old.installedOn=null;}ship.installations[slot]=instanceId;inst.installedOn=shipId;inst.ownerId=ship.owner.id;recalcShip(data,ship);if(shipId===st.activeShipId)syncLegacyShip(data);log(st,`${part(inst.partId).name} installed on ${ship.name}.`,'install');return{ok:true,message:`Installed ${part(inst.partId).name} on ${ship.name}.`};
}
function remove(data,shipId,slot){const st=ensure(data),ship=st.ships[shipId];if(!ship)return{ok:false,message:'Ship unavailable.'};if(F.catalog.classes[ship.classId]?.required?.includes(slot))return{ok:false,message:`${slot} is a required system. Install a replacement instead.`};const iid=ship.installations[slot],inst=iid&&st.components[iid];if(!inst)return{ok:false,message:'Nothing installed in that slot.'};inst.installedOn=null;delete ship.installations[slot];recalcShip(data,ship);if(shipId===st.activeShipId)syncLegacyShip(data);log(st,`${part(inst.partId).name} removed from ${ship.name}.`,'install');return{ok:true,message:`Removed ${part(inst.partId).name}.`};}
function repairCost(inst){const p=part(inst.partId);return Math.max(40,Math.round(Number(p?.credits||1000)*(100-clamp(inst.condition,0,100))/100*.22))}
function repair(data,instanceId){const st=ensure(data),inst=st.components[instanceId];if(!inst)return{ok:false,message:'Component unavailable.'};if(inst.condition>=100)return{ok:false,message:'Component is already at 100%.'};const cost=repairCost(inst);if(Number(data.character?.credits||0)<cost)return{ok:false,message:`Need ${money(cost)} for repairs.`};data.character.credits-=cost;const before=inst.condition;inst.condition=100;inst.damage=[];if(inst.installedOn)recalcShip(data,inst.installedOn);syncLegacyShip(data);log(st,`${part(inst.partId).name} repaired ${before}% → 100% for ${money(cost)}.`,'repair');return{ok:true,message:`${part(inst.partId).name} repaired to 100% for ${money(cost)}.`};}
function damage(data,shipId,amount,seed='impact'){
 const st=ensure(data),ship=st.ships[shipId];if(!ship)return[];const installed=installedInstances(data,ship);if(!installed.length)return[];const r=rng(`${seed}|${shipId}|${ship.damageLog.length}|${amount}`),hits=Math.min(installed.length,Math.max(1,Math.ceil(Number(amount||1)/12))),changed=[];
 for(let i=0;i<hits;i++){const x=installed[Math.floor(r()*installed.length)],loss=Math.max(1,Math.round((Number(amount||1)/hits)*(.55+r()*.55)));x.inst.condition=clamp(x.inst.condition-loss,0,100);x.inst.damage.push({ts:now(),amount:loss,source:String(seed)});x.inst.damage=x.inst.damage.slice(-12);changed.push({partId:x.inst.partId,slot:x.slot,loss,condition:x.inst.condition});}
 ship.damageLog.unshift({ts:now(),source:String(seed),amount:Number(amount||0),components:clone(changed)});ship.damageLog=ship.damageLog.slice(0,30);if(changed.some(x=>x.condition<=0))ship.status='damaged';recalcShip(data,ship);if(shipId===st.activeShipId)syncLegacyShip(data);return changed;
}
function setPalette(data,shipId,paletteId){const st=ensure(data),ship=st.ships[shipId];if(!ship||!F.catalog.palettes.some(p=>p.id===paletteId))return{ok:false,message:'Paint palette unavailable.'};ship.palette=paletteId;recalcShip(data,ship);return{ok:true,message:`${ship.name} repainted: ${paletteId.replaceAll('_',' ')}.`};}
function acquireOwnedShip(data,blueprintOrSeed,opts={}){const st=ensure(data),bp=typeof blueprintOrSeed==='object'?blueprintOrSeed:F.generate(blueprintOrSeed,opts.classId||'light_freighter');const ship=shipFromBlueprint(st,bp,{id:opts.id,name:opts.name||`Owned ${classLabel(bp.classId)}`,ownerId:'rovan',ownerName:data.character?.name||'Rovan Kes',ownerKind:'player',conditions:opts.conditions||{},source:opts.source||'purchase',registry:opts.registry});recalcShip(data,ship);return ship;}

const DEALER_PROFILES={
 new:{suffix:'Component Exchange',kind:'dealer',count:9,minCondition:92,maxCondition:100,markup:1.06},
 salvage:{suffix:'Salvage Yard',kind:'salvage',count:9,minCondition:34,maxCondition:86,markup:.58}
};
function locationName(locationId){return String(locationId||'local').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function dealerId(locationId,kind){return `${locationId}|${kind}`}
function buildDealer(data,locationId,kind,cycle=0){const st=data.shipForge,profile=DEALER_PROFILES[kind],id=dealerId(locationId,kind),r=rng(`${id}|${cycle}|${st.marketCycle}`),pool=F.catalog.parts.slice(),stock=[],used=new Set();for(let i=0;i<profile.count;i++){let p=null;for(let t=0;t<30&&!p;t++){const x=pick(pool,r);if(!used.has(x.id)){p=x;used.add(x.id)}}if(!p)break;const condition=Math.round(profile.minCondition+r()*(profile.maxCondition-profile.minCondition)),rarity=rarityRank(p.rarity),price=Math.max(100,Math.round(p.credits*profile.markup*(.45+.55*condition/100)*(1+(rarity-1)*.035)));stock.push({id:`stock-${hash(`${id}|${cycle}|${i}|${p.id}`).toString(16)}`,partId:p.id,condition,price});}return{id,name:`${locationName(locationId)} ${profile.suffix}`,kind,locationId,cycle,stock,refreshedAt:now()}}
function ensureDealers(data,locationId=currentLocationId(data)){const st=data.shipForge||ensure(data);for(const kind of Object.keys(DEALER_PROFILES)){const id=dealerId(locationId,kind);if(!st.dealers[id])st.dealers[id]=buildDealer(data,locationId,kind,0);}return Object.values(st.dealers).filter(d=>d.locationId===locationId)}
function refreshDealer(data,id){const st=ensure(data),d=st.dealers[id];if(!d)return{ok:false,message:'Dealer unavailable.'};d.cycle=Number(d.cycle||0)+1;st.marketCycle++;st.dealers[id]=buildDealer(data,d.locationId,d.kind,d.cycle);return{ok:true,message:`${d.name} inventory refreshed.`};}
function buy(data,dealerIdValue,stockId){const st=ensure(data),d=st.dealers[dealerIdValue],stock=d?.stock?.find(x=>x.id===stockId);if(!d||!stock)return{ok:false,message:'That listing is no longer available.'};if(Number(data.character?.credits||0)<stock.price)return{ok:false,message:`Need ${money(stock.price)}.`};data.character.credits-=stock.price;const inst=createInstance(st,stock.partId,{condition:stock.condition,ownerId:'rovan',source:d.kind==='salvage'?'salvage-market':'dealer',paid:stock.price});d.stock=d.stock.filter(x=>x.id!==stockId);log(st,`${part(stock.partId).name} purchased from ${d.name} for ${money(stock.price)}.`,'purchase');return{ok:true,message:`Purchased ${part(stock.partId).name} (${stock.condition}%).`,instanceId:inst.id};}
function sell(data,instanceId,dealerIdValue){const st=ensure(data),inst=st.components[instanceId],d=st.dealers[dealerIdValue];if(!inst||!d)return{ok:false,message:'Component or dealer unavailable.'};if(inst.installedOn)return{ok:false,message:'Remove the component before selling it.'};if(inst.ownerId!=='rovan')return{ok:false,message:'You do not own that component.'};const p=part(inst.partId),price=Math.max(20,Math.round(p.credits*(.18+.34*inst.condition/100)));data.character.credits+=price;delete st.components[instanceId];d.stock.push({id:`stock-${hash(`${d.id}|resale|${instanceId}`).toString(16)}`,partId:p.id,condition:inst.condition,price:Math.round(price*1.55)});log(st,`${p.name} sold to ${d.name} for ${money(price)}.`,'sale');return{ok:true,message:`Sold ${p.name} for ${money(price)}.`};}

function npcShip(data,persistentKey,opts={}){const st=ensure(data),key=String(persistentKey);const existingId=st.npcShips[key];if(existingId&&st.ships[existingId]){st.ships[existingId].lastSeenAt=now();return st.ships[existingId];}const classes=opts.classId?[opts.classId]:['fighter','shuttle','light_freighter','patrol','freighter'],r=rng(key),classId=opts.classId||classes[Math.floor(r()*classes.length)],bp=F.generate(hash(key),classId,{palette:opts.palette,registry:opts.registry}),conditions={};for(const slot of Object.keys(bp.parts))conditions[slot]=Math.round(76+r()*24);const id=`npc-${hash(key).toString(16)}`,ship=shipFromBlueprint(st,bp,{id,name:opts.name||`Unknown ${classLabel(classId)}`,ownerId:opts.ownerId||`owner-${hash(key).toString(16)}`,ownerName:opts.ownerName||opts.name||'Unknown Pilot',ownerKind:'npc',persistentKey:key,conditions,source:'npc-persistent',registry:opts.registry});st.npcShips[key]=id;recalcShip(data,ship);return ship;}
function bindDogfightEnemies(data,enemies,ctx={}){const st=ensure(data);st.encounterSerial++;const serial=st.encounterSerial;return(enemies||[]).map((e,i)=>{const classId=/interceptor|fighter|wingman/i.test(e.name)?'fighter':/pursuit|patrol|hunter/i.test(e.name)?'patrol':'light_freighter';const persistent=ctx.ownerKeys?.[i]||e.ownerKey||e.npcId||e.pilotId;const stableKey=persistent?`persistent:${persistent}`:`source:${ctx.source||'space'}:${i}:${e.name}`;const s=npcShip(data,stableKey,{name:e.name,classId,ownerId:persistent||`owner-${hash(stableKey).toString(16)}`,ownerName:e.pilotName||e.name});const ds=effectiveStats(data,s);e.shipForgeId=s.id;e.shipForgeOwner=s.owner.id;e.hpMax=Math.max(18,Math.round(24+ds.effective.armor*3.6+ds.effective.mass*.8));e.hp=e.hp===undefined?e.hpMax:Math.min(Number(e.hp),e.hpMax);e.attackMod=ds.attackMod+Math.max(0,Number(e.threat||1)-1);e.damage=ds.damageFormula;e.shipForgeStats={condition:ds.condition,attackMod:ds.attackMod,evasionBonus:ds.evasionBonus,damageFormula:ds.damageFormula};return e;});}
function damageNpcShip(data,shipId,amount,seed){const st=ensure(data),s=st.ships[shipId];if(!s)return null;const changed=damage(data,shipId,amount,seed);if(s.damageLog.reduce((a,x)=>a+Number(x.amount||0),0)>s.stats.hullMax*.65)s.status='crippled';return{changed,stats:effectiveStats(data,s),ship:s}}
function salvageEncounter(data,enemies,encounterKey){const st=ensure(data),key=String(encounterKey||`dogfight-${st.encounterSerial}`);if(st.salvagedEncounters[key])return[];const defeated=(enemies||[]).filter(e=>Number(e.hp||0)<=0&&e.shipForgeId&&st.ships[e.shipForgeId]);if(!defeated.length){st.salvagedEncounters[key]=true;return[];}const r=rng(`${key}|salvage`),drops=[];for(let i=0;i<defeated.length&&drops.length<2;i++){const s=st.ships[defeated[i].shipForgeId],allInstalled=installedInstances(data,s);const candidates=allInstalled.filter(x=>x.slot!=='core');const x=(candidates.length?pick(candidates,r):pick(allInstalled,r));if(!x)continue;const cond=Math.max(12,Math.min(x.inst.condition,Math.round(28+r()*40)));x.inst.condition=cond;x.inst.installedOn=null;delete s.installations[x.slot];recalcShip(data,s);const drop={id:nextId(st,'salvage'),instanceId:x.inst.id,partId:x.inst.partId,condition:cond,sourceShipId:s.id,sourceName:s.name,claimed:false,createdAt:now()};st.salvage.push(drop);drops.push(drop);s.status='disabled';}
 st.salvagedEncounters[key]=true;if(drops.length)log(st,`${drops.length} salvage component${drops.length>1?'s':''} recovered from ${defeated.map(x=>x.name).join(', ')}.`,'salvage');return drops;}
function claimSalvage(data,dropId){const st=ensure(data),drop=st.salvage.find(x=>x.id===dropId&&!x.claimed);if(!drop)return{ok:false,message:'Salvage claim unavailable.'};let inst=drop.instanceId&&st.components[drop.instanceId];if(inst){inst.ownerId='rovan';inst.installedOn=null;inst.source=`recovered:${drop.sourceShipId}`;inst.notes=`Recovered from ${drop.sourceName}.`;}else inst=createInstance(st,drop.partId,{condition:drop.condition,ownerId:'rovan',source:`recovered:${drop.sourceShipId}`,paid:0,notes:`Recovered from ${drop.sourceName}.`});drop.claimed=true;drop.claimedAt=now();log(st,`${part(drop.partId).name} claimed from salvage.`,'salvage');return{ok:true,message:`Recovered ${part(drop.partId).name} at ${drop.condition}% condition.`,instanceId:inst.id};}

function trafficPopulation(data,key,count=4,classIds=['fighter','shuttle','light_freighter','freighter','cargo','patrol']){const st=ensure(data),k=String(key);st.traffic[k]=st.traffic[k]||[];const ids=st.traffic[k];while(ids.length<count){const i=ids.length,seed=hash(`${k}|${i}`),classId=classIds[seed%classIds.length]||'light_freighter',bp=F.generate(seed,classId),ship=shipFromBlueprint(st,bp,{id:`traffic-${hash(`${k}|${i}`).toString(16)}`,name:`${classLabel(classId)} Traffic ${i+1}`,ownerId:`traffic-owner-${hash(`${k}|${i}|owner`).toString(16)}`,ownerName:'Ambient Traffic',ownerKind:'ambient',source:'traffic',conditions:Object.fromEntries(Object.keys(bp.parts).map(s=>[s,85+(seed+s.length)%16]))});ids.push(ship.id);}return ids.slice(0,count).map(id=>({record:st.ships[id],blueprint:blueprint(data,id)}));}

function renderStats(stats){const d=stats;return`<div class="sfw-stats"><span><b>${d.hullMax}</b> HULL</span><span><b>${d.shieldsMax}</b> SHIELDS</span><span><b>${d.effective.speed.toFixed(1)}</b> SPEED</span><span><b>${d.effective.damage.toFixed(1)}</b> WEAPONS</span><span><b>${d.effective.capacity.toFixed(1)}</b> CARGO</span><span><b>${d.condition}%</b> CONDITION</span></div>`}
function actionBtn(action,label,a='',b='',cls=''){return`<button class="btn ${cls}" data-sf-action="${esc(action)}" data-sf-a="${esc(a)}" data-sf-b="${esc(b)}">${esc(label)}</button>`}
function renderInstalled(data,ship){const st=ensure(data),rows=slots.filter(s=>ship.installations[s]).map(slot=>{const inst=st.components[ship.installations[slot]],p=part(inst.partId),required=F.catalog.classes[ship.classId].required.includes(slot),cost=repairCost(inst);return`<div class="sfw-part-row"><div class="sfw-part-art">${F.renderPartSVG(p.id,{palette:ship.palette})}</div><div class="sfw-part-copy"><span class="micro">${esc(slot.toUpperCase())} // ${esc(p.manufacturer)}</span><b>${esc(p.name)}</b><small>${esc(p.rarity.toUpperCase())} · ${inst.condition}% ${conditionLabel(inst.condition)} · ${money(p.credits)}</small><div class="sfw-cond"><i style="width:${inst.condition}%"></i></div></div><div class="sfw-part-actions">${inst.condition<100?actionBtn('repair',`Repair ${money(cost)}`,inst.id,'','good'):''}${!required?actionBtn('remove','Remove',ship.id,slot):'<span class="pill">REQUIRED</span>'}</div></div>`}).join('');return rows||'<p class="muted">No components installed.</p>'}
function renderLocker(data,ship,dealers){const inv=inventory(data),sellDealer=dealers.find(d=>d.kind==='salvage')||dealers[0];if(!inv.length)return'<p class="muted">Parts locker empty. Buy, salvage, or remove a component to store it here.</p>';return`<div class="sfw-locker">${inv.map(inst=>{const p=part(inst.partId),fit=canInstall(data,ship,inst);return`<div class="sfw-locker-item"><div>${F.renderPartSVG(p.id,{palette:ship.palette})}</div><b>${esc(p.name)}</b><small>${esc(p.slot.toUpperCase())} · ${inst.condition}% · ${esc(p.manufacturer)}</small><div class="controls">${fit?actionBtn('install',`Install ${p.slot}`,ship.id,inst.id,'good'):''}${inst.condition<100?actionBtn('repair','Repair',inst.id):''}${sellDealer?actionBtn('sell','Sell',inst.id,sellDealer.id,'warn'):''}</div></div>`}).join('')}</div>`}
function renderDealer(data,d,ship){return`<section class="sfw-dealer"><div class="row"><div><span class="micro">${d.kind==='salvage'?'USED / RECOVERED':'NEW COMPONENTS'}</span><h4>${esc(d.name)}</h4></div>${actionBtn('refresh','Refresh',d.id)}</div><div class="sfw-stock">${d.stock.map(s=>{const p=part(s.partId),fit=F.compatible(p,ship.classId);return`<div class="sfw-stock-item ${fit?'':'sfw-no-fit'}"><div class="sfw-stock-art">${F.renderPartSVG(p.id,{palette:ship.palette})}</div><div><b>${esc(p.name)}</b><small>${esc(p.manufacturer)} · ${esc(p.rarity.toUpperCase())}<br>${s.condition}% ${conditionLabel(s.condition)} · ${fit?'FITS CURRENT SHIP':'INCOMPATIBLE'}</small></div><strong>${money(s.price)}</strong>${actionBtn('buy','Buy',d.id,s.id,fit?'good':'')}</div>`}).join('')}</div></section>`}
function renderShipyard(data){const st=ensure(data),ship=st.ships[st.managedShipId]||st.ships[st.activeShipId],bp=blueprint(data,ship),stats=effectiveStats(data,ship),dealers=ensureDealers(data,currentLocationId(data)),salvage=st.salvage.filter(x=>!x.claimed),fleet=playerShips(data);return`<div class="sfw-yard"><section class="sfw-hero"><div class="sfw-hero-visual">${F.renderMarkup(bp,{label:`${ship.name} modular build`})}</div><div class="sfw-hero-copy"><span class="micro">SHIPFORGE PHASE 2 // PERSISTENT BUILD</span><h3>${esc(ship.name)}</h3><p>${esc(classLabel(ship.classId))} · ${esc(ship.registry||'UNREGISTERED')} · Owner: ${esc(ship.owner.name)}</p>${renderStats(stats)}<div class="sfw-palette">${F.catalog.palettes.map(p=>actionBtn('paint',p.id.replaceAll('_',' '),ship.id,p.id,p.id===ship.palette?'good':'')).join('')}</div></div></section><div class="sfw-grid"><section><div class="row"><h3>Installed Components</h3><span class="pill cyan">STATS ARE LIVE</span></div>${renderInstalled(data,ship)}</section><section><div class="row"><h3>Parts Locker</h3><span class="pill">${inventory(data).length} STORED</span></div>${renderLocker(data,ship,dealers)}</section></div>${salvage.length?`<section class="sfw-salvage"><div class="row"><h3>Recovered Salvage</h3><span class="pill warn">${salvage.length} CLAIMS</span></div>${salvage.map(x=>{const p=part(x.partId);return`<div class="sfw-salvage-item"><b>${esc(p.name)}</b><span>${x.condition}% · recovered from ${esc(x.sourceName)}</span>${actionBtn('claim','Claim',x.id,'','good')}</div>`}).join('')}</section>`:''}<section><div class="row"><h3>Local Component Market</h3><span class="muted">${esc(locationName(currentLocationId(data)))}</span></div><div class="sfw-dealers">${dealers.map(d=>renderDealer(data,d,ship)).join('')}</div></section><section><div class="row"><h3>Owned Ship Registry</h3><span class="pill">${fleet.length} SHIP${fleet.length===1?'':'S'}</span></div><div class="sfw-fleet">${fleet.map(s=>`<div class="sfw-fleet-item ${s.id===ship.id?'active':''}"><b>${esc(s.name)}</b><span>${esc(classLabel(s.classId))} · ${esc(s.registry||'UNREGISTERED')}</span><small>${Object.keys(s.installations||{}).length} installed components · ${s.stats?.condition??100}% avg condition</small>${actionBtn('manage',s.id===ship.id?'MANAGING':'Manage',s.id,'',s.id===ship.id?'good':'')}</div>`).join('')}</div></section></div>`}
function handleAction(data,action,a,b){switch(action){case'buy':return buy(data,a,b);case'sell':return sell(data,a,b);case'install':return install(data,a,b);case'remove':return remove(data,a,b);case'repair':return repair(data,a);case'claim':return claimSalvage(data,a);case'refresh':return refreshDealer(data,a);case'paint':return setPalette(data,a,b);case'manage':{const st=ensure(data),ship=st.ships[a];if(!ship||ship.owner?.kind!=='player')return{ok:false,message:'Owned ship unavailable.'};st.managedShipId=a;return{ok:true,message:`Managing ${ship.name}.`}}default:return{ok:false,message:'Unknown ShipForge action.'}}}

root.DeadlockShipForge={schema:SCHEMA,version:VERSION,ensure,state,shipRecord,blueprint,effectiveStats,recalcShip,syncLegacyShip,inventory,playerShips,createInstance,acquireOwnedShip,install,remove,repair,repairCost,damage,setPalette,ensureDealers,refreshDealer,buy,sell,npcShip,bindDogfightEnemies,damageNpcShip,salvageEncounter,claimSalvage,trafficPopulation,renderShipyard,handleAction,conditionLabel,canInstall};
})(typeof window!=='undefined'?window:globalThis);
